35	template <typename T>
36	static std::string TilingData2Str(void* buf, size_t size)
37	{
38	    std::string result;
39	    const T* data = reinterpret_cast<const T*>(buf);
40	    size_t len = size / sizeof(T);
41	    for (size_t i = 0; i < len; i++) {
42	        result += std::to_string(data[i]);
43	        result += " ";
44	    }
45	    return result;
46	}
47	
48	// ========================== 正常用例 ==========================
49	
50	/*
51	 * 测试用例描述：ScatterBlockUpdate算子tiling功能验证 — 连续input，网络典型值
52	 * 输入：
53	 *   - var: shape (b_n, b_s, D) = (2048, 128, 128), dtype = FP32, 连续
54	 *   - indices: shape (T, 2) = (16384, 2), dtype = INT32
55	 *   - updates: shape (T, D) = (16384, 128), dtype = FP32
56	 *   shape约束: b_n=[1,16K], b_s=[1,1024], D=[1,256], T=[1,256K]
57	 * 预期结果：tiling正常执行，返回GRAPH_SUCCESS
58	 */
59	TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Normal_contiguous)
60	{
61	    int64_t b_n = 2048;
62	    int64_t b_s = 128;
63	    int64_t D = 128;
64	    int64_t T = 16384;
65	
66	    optiling::AiInfraScatterBlockUpdateCompileInfo compileInfo = {};
67	    gert::TilingContextPara tilingContextPara("AiInfraScatterBlockUpdate",
68	        {
69	            // input 0: var, shape (b_n, b_s, D) = (2048, 128, 128), FP32, 连续
70	            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
71	            // input 1: indices, shape (T, 2) = (16384, 2), INT32
72	            {{{T, 2}, {T, 2}}, ge::DT_INT32, ge::FORMAT_ND},
73	            // input 2: updates, shape (T, D) = (16384, 128), FP32
74	            {{{T, D}, {T, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
75	        },
76	        {
77	            // output 0: var, shape (b_n, b_s, D), FP32
78	            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
79	        },
80	        {},  // no attrs
81	        &compileInfo
82	    );
83	
84	    uint64_t expectTilingKey = 1000;
85	    std::string expectTilingDataStr = "";
86	    std::vector<size_t> expectWorkspaces = {0};
87	    ExecuteTestCase(tilingContextPara, ge::GRAPH_SUCCESS, expectTilingKey,
88	                    expectTilingDataStr, expectWorkspaces, 0, TilingData2Str<int64_t>);
89	}
90	
91	/*
92	 * 测试用例描述：ScatterBlockUpdate算子tiling功能验证 — 非连续input
93	 * 说明：当前tiling UT框架（TilingContextPara）不支持设置view/stride,
94	 *       InputIsView()始终返回false，因此无法覆盖非连续tensor的tiling路径。
95	 *       此用例使用不同的shape值验证连续路径正常工作。
96	 *       非连续路径的验证需要在op_api UT或ST层面完成。
97	 * 输入：
98	 *   - var: shape (b_n, b_s, D) = (512, 64, 64), dtype = BF16, 连续（框架限制）
99	 *   - indices: shape (T, 2) = (4096, 2), dtype = INT32
100	 *   - updates: shape (T, D) = (4096, 64), dtype = BF16
101	 * 预期结果：tiling正常执行，返回GRAPH_SUCCESS
102	 */
103	TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Normal_incontiguous)
104	{
105	    int64_t b_n = 512;
106	    int64_t b_s = 64;
107	    int64_t D = 64;
108	    int64_t T = 4096;
109	
110	    optiling::AiInfraScatterBlockUpdateCompileInfo compileInfo = {};
111	    gert::TilingContextPara tilingContextPara("AiInfraScatterBlockUpdate",
112	        {
113	            // input 0: var, shape (b_n, b_s, D) = (512, 64, 64), BF16
114	            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_BF16, ge::FORMAT_ND},
115	            // input 1: indices, shape (T, 2) = (4096, 2), INT32
116	            {{{T, 2}, {T, 2}}, ge::DT_INT32, ge::FORMAT_ND},
117	            // input 2: updates, shape (T, D) = (4096, 64), BF16
118	            {{{T, D}, {T, D}}, ge::DT_BF16, ge::FORMAT_ND},
119	        },
120	        {
121	            // output 0: var, shape (b_n, b_s, D), BF16
122	            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_BF16, ge::FORMAT_ND},
123	        },
124	        {},
125	        &compileInfo
126	    );
127	
128	    uint64_t expectTilingKey = 1000;
