/*!
 * \file ai_infra_scatter_block_update_tiling.cpp
 * \brief
 */

#include <algorithm>
#include "../../../common/include/tiling_base/tiling_templates_registry.h"
#include "register/op_def_registry.h"
#include "platform/platform_infos_def.h"
#include "../../../common/include/err/ops_err.h"
#include "ai_infra_scatter_block_update_tiling.h"

namespace optiling {

using namespace Ops::Transformer::OpTiling;

// 输入tensor索引
static constexpr uint32_t INPUT_VAR_INDEX = 0;
static constexpr uint32_t INPUT_INDICES_INDEX = 1;
static constexpr uint32_t INPUT_UPDATE_INDEX = 2;

// 维度常量
static constexpr int64_t INPUT_DIM_NUM = 3;     // input shape: (b_n, b_s, D)
static constexpr int64_t INDICES_DIM_NUM = 2;   // indices shape: (T, 2)
static constexpr int64_t UPDATE_DIM_NUM = 2;    // update shape: (T, D)
static constexpr int64_t INDICES_LAST_DIM = 2;  // indices最后一维固定为2

// input维度索引
static constexpr int64_t INPUT_DIM_BN_INDEX = 0;  // input第0维索引 (b_n)
static constexpr int64_t INPUT_DIM_BS_INDEX = 1;  // input第1维索引 (b_s)
static constexpr int64_t INPUT_DIM_D_INDEX = 2;   // input第2维索引 (D)

// 内存对齐与UB布局
static constexpr int64_t ALIGN_BYTES = 32;
static constexpr int64_t RESERVED_UB_SIZE = 4 * 1024;  // 4KB预留给栈和临时变量
static constexpr int64_t DOUBLE_BUFFER_NUM = 2;
static constexpr int64_t DATA_COPY_MAX_BLOCK = 4064;

// shape取值范围约束 (闭区间)
static constexpr int64_t BN_MIN = 1;
static constexpr int64_t BN_MAX = 2 * 1024 * 1024;       // 2M
static constexpr int64_t BS_MIN = 1;
static constexpr int64_t BS_MAX = 1024;
static constexpr int64_t D_MIN = 1;
static constexpr int64_t D_MAX = 2048;
static constexpr int64_t T_MIN = 1;
static constexpr int64_t T_MAX = 1024 * 1024;       // 1M

static constexpr uint64_t FULL_LOAD_TILING_KEY = 1000;


static inline int64_t AlignUp(int64_t size, int64_t alignment)
{
    if (alignment <= 0) {
        return size;
    }
    return (size + alignment - 1) / alignment * alignment;
}

static inline int64_t CeilDiv(int64_t a, int64_t b)
{
    if (b <= 0) {
        return a;
    }
    return (a + b - 1) / b;
}

REGISTER_TILING_TEMPLATE("AiInfraScatterBlockUpdate", AiInfraScatterBlockUpdateBaseTiling, 1000);


ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetPlatformInfo()
{
    uint64_t aivNum = 40;
    uint64_t ubSize = 192 * 1024; // 192k: default ubSize
    auto platformInfoPtr = context_->GetPlatformInfo();
    if (platformInfoPtr == nullptr) {
        auto compilePtr = reinterpret_cast<const AiInfraScatterBlockUpdateCompileInfo *>(context_->GetCompileInfo());
        OP_CHECK_IF(compilePtr == nullptr, OP_LOGE(context_, "compile_info is null"),
                    return ge::GRAPH_FAILED);
        aivNum = compilePtr->aivNum;
        ubSize = compilePtr->ubSize;
    } else {
        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
        aivNum = ascendcPlatform.GetCoreNumAiv();
        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    }
    aivNum_ = aivNum;
    ubSize_ = static_cast<int64_t>(ubSize);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetInputShapeAndStride()
{
    // ========== 获取input (var) 信息: shape (b_n, b_s, D), 支持第0维非连续 ==========
    auto inputDesc = context_->GetInputDesc(INPUT_VAR_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, inputDesc);
    inputDtype_ = inputDesc->GetDataType();

    // 校验input数据类型: 仅支持FP32/BF16/FP16/INT8
    OP_CHECK_IF(inputDtype_ != ge::DT_FLOAT && inputDtype_ != ge::DT_BF16 &&
                inputDtype_ != ge::DT_FLOAT16 && inputDtype_ != ge::DT_INT8,
        OP_LOGE(context_->GetNodeName(), "input dtype only supports FP32/BF16/FP16/INT8"),
        return ge::GRAPH_FAILED);

    // 获取input shape和stride
    auto inputShapePtr = context_->GetInputShape(INPUT_VAR_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, inputShapePtr);

    auto* inputStride = context_->GetInputStride(INPUT_VAR_INDEX);
    if (inputStride != nullptr && inputStride->GetDimNum() > 0) {
        // 非连续tensor，通过input stride判断
        auto viewShape = inputShapePtr->GetShape();
        OP_CHECK_IF(viewShape.GetDimNum() != static_cast<size_t>(INPUT_DIM_NUM),
            OP_LOGE(context_->GetNodeName(),
                    "input should be 3D (b_n, b_s, D), but got %zu dims", viewShape.GetDimNum()),
            return ge::GRAPH_FAILED);
        bn_ = viewShape.GetDim(INPUT_DIM_BN_INDEX);
        bs_ = viewShape.GetDim(INPUT_DIM_BS_INDEX);
        D_ = viewShape.GetDim(INPUT_DIM_D_INDEX);
        inputStride0_ = (*inputStride)[0];
        inputStride1_ = (*inputStride)[1];
    } else {
        // 连续tensor, 从originShape计算stride
        auto originShape = inputShapePtr->GetOriginShape();
        OP_CHECK_IF(originShape.GetDimNum() != static_cast<size_t>(INPUT_DIM_NUM),
            OP_LOGE(context_->GetNodeName(),
                    "input should be 3D (b_n, b_s, D), but got %zu dims", originShape.GetDimNum()),
            return ge::GRAPH_FAILED);
        bn_ = originShape.GetDim(INPUT_DIM_BN_INDEX);
        bs_ = originShape.GetDim(INPUT_DIM_BS_INDEX);
        D_ = originShape.GetDim(INPUT_DIM_D_INDEX);
        inputStride0_ = bs_ * D_;
        inputStride1_ = D_;
    }
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetIndicesShape()
{
    // ========== 获取indices信息: shape (T, 2), 连续, INT32/INT64 ==========
    auto indicesDesc = context_->GetInputDesc(INPUT_INDICES_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, indicesDesc);
    indicesDtype_ = indicesDesc->GetDataType();

    OP_CHECK_IF(indicesDtype_ != ge::DT_INT32 && indicesDtype_ != ge::DT_INT64,
        OP_LOGE(context_->GetNodeName(), "indices dtype only supports INT32/INT64"),
        return ge::GRAPH_FAILED);

    auto indicesShapePtr = context_->GetInputShape(INPUT_INDICES_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, indicesShapePtr);
    auto indicesShape = indicesShapePtr->GetStorageShape();

    OP_CHECK_IF(indicesShape.GetDimNum() != static_cast<size_t>(INDICES_DIM_NUM),
        OP_LOGE(context_->GetNodeName(),
                "indices should be 2D (T, 2), but got %zu dims", indicesShape.GetDimNum()),
        return ge::GRAPH_FAILED);

    T_ = indicesShape.GetDim(0);
    int64_t indicesDim1 = indicesShape.GetDim(1);
    OP_CHECK_IF(indicesDim1 != INDICES_LAST_DIM,
        OP_LOGE(context_->GetNodeName(), "indices last dim should be 2, but got %ld", indicesDim1),
        return ge::GRAPH_FAILED);
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetUpdateShape()
{
    // ========== 获取update信息: shape (T, D), 连续, 与input同dtype ==========
    auto updateDesc = context_->GetInputDesc(INPUT_UPDATE_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, updateDesc);
    auto updateDtype = updateDesc->GetDataType();

    OP_CHECK_IF(updateDtype != inputDtype_,
        OP_LOGE(context_->GetNodeName(), "update dtype should be same as input dtype"),
        return ge::GRAPH_FAILED);

    auto updateShapePtr = context_->GetInputShape(INPUT_UPDATE_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, updateShapePtr);
    auto updateShape = updateShapePtr->GetStorageShape();

    OP_CHECK_IF(updateShape.GetDimNum() != static_cast<size_t>(UPDATE_DIM_NUM),
        OP_LOGE(context_->GetNodeName(),
                "update should be 2D (T, D), but got %zu dims", updateShape.GetDimNum()),
        return ge::GRAPH_FAILED);

    int64_t updateT = updateShape.GetDim(0);
    updateDimSize_ = updateShape.GetDim(1);

    // 校验indices和update的T维一致
    OP_CHECK_IF(updateT != T_,
        OP_LOGE(context_->GetNodeName(),
                "update dim0(%ld) should match indices dim0(%ld)", updateT, T_),
        return ge::GRAPH_FAILED);

    // 校验update的D维与input的D维一致
    OP_CHECK_IF(updateDimSize_ != D_,
        OP_LOGE(context_->GetNodeName(),
                "update dim1(%ld) should match input dim2(%ld)", updateDimSize_, D_),
        return ge::GRAPH_FAILED);
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::ValidateShapeRange()
{
    // ========== shape取值范围校验 ==========
    OP_CHECK_IF(bn_ < BN_MIN || bn_ > BN_MAX,
        OP_LOGE(context_->GetNodeName(),
                "b_n(%ld) out of range [%ld, %ld]", bn_, BN_MIN, BN_MAX),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(bs_ < BS_MIN || bs_ > BS_MAX,
        OP_LOGE(context_->GetNodeName(),
                "b_s(%ld) out of range [%ld, %ld]", bs_, BS_MIN, BS_MAX),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(D_ < D_MIN || D_ > D_MAX,
        OP_LOGE(context_->GetNodeName(),
                "D(%ld) out of range [%ld, %ld]", D_, D_MIN, D_MAX),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(T_ < T_MIN || T_ > T_MAX,
        OP_LOGE(context_->GetNodeName(),
                "T(%ld) out of range [%ld, %ld]", T_, T_MIN, T_MAX),
        return ge::GRAPH_FAILED);
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::CalcDataTypeSize()
{
    // ========== 计算数据类型大小 ==========
    indicesTypeSize_ = ge::GetSizeByDataType(indicesDtype_);
    OP_CHECK_IF(indicesTypeSize_ <= 0,
        OP_LOGE(context_->GetNodeName(), "get indicesTypeSize failed"),
        return ge::GRAPH_FAILED);

    updateTypeSize_ = ge::GetSizeByDataType(inputDtype_);
    OP_CHECK_IF(updateTypeSize_ <= 0,
        OP_LOGE(context_->GetNodeName(), "get updateTypeSize failed"),
        return ge::GRAPH_FAILED);
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetAndCheckInputShape()
{
    if (GetInputShapeAndStride() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    if (GetIndicesShape() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    if (GetUpdateShape() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    if (ValidateShapeRange() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    if (CalcDataTypeSize() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }

    OP_LOGD(context_->GetNodeName(),
        "input: (%ld,%ld,%ld), stride: (%ld,%ld), indices: (%ld,2), "
        "update: (%ld,%ld), indicesTypeSize=%ld, updateTypeSize=%ld",
        bn_, bs_, D_, inputStride0_, inputStride1_,
        T_, T_, updateDimSize_, indicesTypeSize_, updateTypeSize_);

    return ge::GRAPH_SUCCESS;
}


ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::DoOpTiling()
{
    if (GetAndCheckInputShape() != ge::GRAPH_SUCCESS) {
        OP_LOGE(context_->GetNodeName(), "GetAndCheckInputShape failed!");
        return ge::GRAPH_FAILED;
    }

    totalIndicesCount_ = T_;
    totalCoreNum_ = static_cast<int32_t>(aivNum_);

    // 处理空tensor
    if (totalIndicesCount_ == 0) {
        usedCoreNum_ = 1;
        eachCoreIndexCount_ = 0;
        tailCoreIndexCount_ = 0;
        oneIndexSize_ = 0;
        oneUpdateAlignSize_ = 0;
        indicesPerLoad_ = 0;
        maxIndicesPerLoad_ = 0;
        return ge::GRAPH_SUCCESS;
    }

    // ========== 步骤1: 计算对齐后的每行数据大小 ==========
    // 一行indices: 2个元素 * indicesTypeSize 字节, 用GetValue取出，不需要对齐
    oneIndexSize_ = INDICES_LAST_DIM * indicesTypeSize_;
    // 一行update: D个元素 * updateTypeSize 字节, 对齐到32字节
    oneUpdateAlignSize_ = AlignUp(D_ * updateTypeSize_, ALIGN_BYTES);

    // ========== 步骤2: 分核策略 ==========
    // 按indices行数均分到各核
    eachCoreIndexCount_ = CeilDiv(totalIndicesCount_, static_cast<int64_t>(totalCoreNum_));
    // 实际使用的核数（可能小于totalCoreNum）
    usedCoreNum_ = static_cast<int32_t>(CeilDiv(totalIndicesCount_, eachCoreIndexCount_));
    // 最后一个核处理的行数（尾块）
    tailCoreIndexCount_ = totalIndicesCount_ - eachCoreIndexCount_ * (usedCoreNum_ - 1);

    // ========== 步骤3: UB内存计算 (double buffer) ==========
    // 预留一部分UB空间给栈和临时变量
    int64_t availableUbSize = ubSize_ - RESERVED_UB_SIZE;
    OP_CHECK_IF(availableUbSize <= 0,
        OP_LOGE(context_->GetNodeName(),
                "UB size(%ld) too small after reserving %ld bytes", ubSize_, RESERVED_UB_SIZE),
        return ge::GRAPH_FAILED);

    // double buffer: 可用UB分两半
    int64_t halfUbSize = availableUbSize / DOUBLE_BUFFER_NUM;

    // 每半UB能装多少行 indices + update
    int64_t perLoadSize = oneIndexSize_ + oneUpdateAlignSize_;
    OP_CHECK_IF(perLoadSize <= 0,
        OP_LOGE(context_->GetNodeName(), "perLoadSize should be positive"),
        return ge::GRAPH_FAILED);

    indicesPerLoad_ = halfUbSize / perLoadSize;
    OP_CHECK_IF(indicesPerLoad_ <= 0,
        OP_LOGE(context_->GetNodeName(),
                "UB too small for 1 row, halfUb=%ld, oneIndex=%ld, oneUpdate=%ld",
                halfUbSize, oneIndexSize_, oneUpdateAlignSize_),
        return ge::GRAPH_FAILED);

    // ========== 步骤4: 限制最大加载行数不超过每核处理量 ==========
    maxIndicesPerLoad_ = std::min(eachCoreIndexCount_, indicesPerLoad_);
    maxIndicesPerLoad_ = std::min(maxIndicesPerLoad_, static_cast<int64_t>(DATA_COPY_MAX_BLOCK));

    OP_LOGD(context_->GetNodeName(),
        "totalIndices=%ld, usedCores=%d, eachCore=%ld, tail=%ld, perLoad=%ld, "
        "maxPerLoad=%ld, oneIdx=%ld, oneUpd=%ld",
        totalIndicesCount_, usedCoreNum_, eachCoreIndexCount_,
        tailCoreIndexCount_, indicesPerLoad_, maxIndicesPerLoad_,
        oneIndexSize_, oneUpdateAlignSize_);

    tilingKey_ = FULL_LOAD_TILING_KEY;

    return ge::GRAPH_SUCCESS;
}

void AiInfraScatterBlockUpdateBaseTiling::PrintTilingData()
{
    OP_LOGD(context_->GetNodeName(),
        "TilingData: totalIndicesCount=%ld, updateDimSize=%ld, usedCoreNum=%d, "
        "eachCoreIndexCount=%ld, tailCoreIndexCount=%ld, oneIndexAlign=%ld, "
        "oneUpdateAlign=%ld, indicesPerLoad=%ld, maxIndicesPerLoad=%ld, "
        "inputStride0=%ld, inputStride1=%ld, indicesTypeSize=%ld, updateTypeSize=%ld",
        tilingData_.get_totalIndicesCount(), tilingData_.get_updateDimSize(),
        tilingData_.get_usedCoreNum(), tilingData_.get_eachCoreIndexCount(),
        tilingData_.get_tailCoreIndexCount(), tilingData_.get_oneIndexSize(),
        tilingData_.get_oneUpdateAlignSize(), tilingData_.get_indicesPerLoad(),
        tilingData_.get_maxIndicesPerLoad(), tilingData_.get_inputStride0(),
        tilingData_.get_inputStride1(), tilingData_.get_indicesTypeSize(),
        tilingData_.get_updateTypeSize());
}

uint64_t AiInfraScatterBlockUpdateBaseTiling::GetTilingKey() const
{
    return tilingKey_;
}

ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::PostTiling()
{
    // ========== 设置所有TilingData字段 ==========
    tilingData_.set_totalIndicesCount(totalIndicesCount_);
    tilingData_.set_updateDimSize(updateDimSize_);
    tilingData_.set_totalCoreNum(totalCoreNum_);
    tilingData_.set_ubSize(ubSize_);
    tilingData_.set_eachCoreIndexCount(eachCoreIndexCount_);
    tilingData_.set_usedCoreNum(usedCoreNum_);
    tilingData_.set_tailCoreIndexCount(tailCoreIndexCount_);
    tilingData_.set_oneIndexSize(oneIndexSize_);
    tilingData_.set_oneUpdateAlignSize(oneUpdateAlignSize_);
    tilingData_.set_indicesPerLoad(indicesPerLoad_);
    tilingData_.set_maxIndicesPerLoad(maxIndicesPerLoad_);
    tilingData_.set_inputStride0(inputStride0_);
    tilingData_.set_inputStride1(inputStride1_);
    tilingData_.set_indicesTypeSize(indicesTypeSize_);
    tilingData_.set_updateTypeSize(updateTypeSize_);

    PrintTilingData();

    // 校验TilingData大小对齐到8字节
    OP_CHECK_IF(tilingData_.GetDataSize() % sizeof(uint64_t) != 0,
        OP_LOGE(context_->GetNodeName(), "tiling data size[%zu] is not aligned to 8", tilingData_.GetDataSize()),
        return ge::GRAPH_FAILED);

    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetRawTilingData());
    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());

    // 设置block维度（实际使用的核数）
    context_->SetBlockDim(usedCoreNum_);

    // 设置workspace（本算子为原地更新，不需要额外workspace）
    size_t *workspaces = context_->GetWorkspaceSizes(1);
    OP_CHECK_IF(workspaces == nullptr, OPS_REPORT_CUBE_INNER_ERR(context_->GetNodeName(), "workspaces is null"),
        return ge::GRAPH_FAILED);
    workspaces[0] = workspaceSize_;

    return ge::GRAPH_SUCCESS;
}

static ge::graphStatus TilingFunc4ScatterBlockUpdate(gert::TilingContext* context)
{
    OP_CHECK_IF(context == nullptr,
        OPS_REPORT_CUBE_INNER_ERR("[TilingFunc4ScatterBlockUpdate]", "context is null"),
        return ge::GRAPH_FAILED);

    return Ops::Transformer::OpTiling::TilingRegistry::GetInstance().DoTilingImpl(context);
}


static ge::graphStatus TilingPrepare4ScatterBlockUpdate(gert::TilingParseContext* context)
{
    OP_CHECK_IF(context == nullptr,
                OPS_REPORT_CUBE_INNER_ERR("[TilingPrepare4ScatterBlockUpdate]", "context is null"),
                return ge::GRAPH_FAILED);
    fe::PlatFormInfos* platformInfo = context->GetPlatformInfo();
    OP_CHECK_IF(platformInfo == nullptr,
                OPS_REPORT_CUBE_INNER_ERR(context->GetNodeName(), "platformInfoPtr is null"),
                return ge::GRAPH_FAILED);

    auto compileInfoPtr = context->GetCompiledInfo<AiInfraScatterBlockUpdateCompileInfo>();
    OP_CHECK_IF(compileInfoPtr == nullptr,
                OPS_REPORT_CUBE_INNER_ERR(context->GetNodeName(), "compileInfoPtr is null"),
                return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);

    compileInfoPtr->aivNum = ascendcPlatform.GetCoreNumAiv();

    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);

    return ge::GRAPH_SUCCESS;
}

IMPL_OP_OPTILING(AiInfraScatterBlockUpdate)
    .Tiling(TilingFunc4ScatterBlockUpdate)
    .TilingParse<AiInfraScatterBlockUpdateCompileInfo>(TilingPrepare4ScatterBlockUpdate);
}

